using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Modules;[Authorize(Policy="SuperAdminOnly")]public sealed class IndexModel(OrcaFacilDbContext db):PageModel{public IReadOnlyList<Row>Modules{get;private set;}=[];public async Task OnGetAsync(CancellationToken ct)=>Modules=await db.SaasModules.AsNoTracking().Where(x=>!x.IsDeleted).OrderBy(x=>x.DisplayOrder).Select(x=>new Row(x.Id,x.Code,x.DisplayName,x.Category,x.BaseMonthlyPrice,x.BaseAnnualPrice,x.RoutePrefix,x.RequiredPermissionCode,x.IsActive)).ToListAsync(ct);public sealed record Row(Guid Id,string Code,string Name,string Category,decimal Monthly,decimal Annual,string Route,string Permission,bool Active);}
